Read the active sheet’s cached values and locate the “Match from D” and “Match from B” criteria columns, defaulting to sensible columns if headers are missing. For rows 7–9, scan B2:B23 and D2:D23 in order for the first row where both criteria match, then take the corresponding F text. Write those three stripped text values into L7:L9.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title if vals.active is not None else "Sheet1"
ws_vals = vals[sheet_name]
ws = wb[sheet_name]

def is_blank(v):
    if v is None:
        return True
    if isinstance(v, str) and v.strip() == "":
        return True
    return False

def norm_header(v):
    if v is None:
        return ""
    return " ".join(str(v).split()).lower()

def num_key(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        try:
            return float(s)
        except ValueError:
            return s
    return v

def eq_b(a, b):
    if is_blank(a) or is_blank(b):
        return False
    na, nb = num_key(a), num_key(b)
    if isinstance(na, float) and isinstance(nb, float):
        return na == nb
    if isinstance(na, str) and isinstance(nb, str):
        return na == nb
    return str(a).strip() == str(b).strip()

def eq_d(a, b):
    if is_blank(a) or is_blank(b):
        return False
    return str(a).strip() == str(b).strip()

max_col = min(ws_vals.max_column or 12, 12)
col_d = None
col_b = None

for c in range(1, max_col + 1):
    h = norm_header(ws_vals.cell(row=6, column=c).value)
    if "match from d" in h:
        col_d = c
    if "match from b" in h:
        col_b = c

if col_d == col_b:
    col_b = None

def has_criteria(cd, cb):
    if cd is None or cb is None:
        return False
    for r in range(7, 10):
        if not is_blank(ws_vals.cell(row=r, column=cd).value) and not is_blank(ws_vals.cell(row=r, column=cb).value):
            return True
    return False

if not has_criteria(col_d, col_b):
    d_set = set()
    b_set = set()

    for r in range(2, 24):
        dv = ws_vals.cell(row=r, column=4).value
        bv = ws_vals.cell(row=r, column=2).value

        if not is_blank(dv):
            d_set.add(str(dv).strip())

        if not is_blank(bv):
            key = num_key(bv)
            if key is not None and not (isinstance(key, str) and key == ""):
                b_set.add(key)

    candidates = [10, 11, 12, 9, 8, 7, 4, 5, 3, 1, 2]
    for c in candidates:
        if c > max_col:
            continue
        sample = [ws_vals.cell(row=r, column=c).value for r in range(7, 10)]

        if col_d is None and all(not is_blank(v) and str(v).strip() in d_set for v in sample):
            col_d = c

        if col_b is None and all(not is_blank(v) and num_key(v) in b_set for v in sample):
            col_b = c

    if col_d is None:
        col_d = 10
    if col_b is None:
        col_b = 11

if col_d is None or col_d > max_col:
    col_d = 10
if col_b is None or col_b > max_col:
    col_b = 11

if col_d == col_b:
    if col_d == 12:
        col_d = 11
    else:
        col_b = 12

results = []
for r in range(7, 10):
    d_crit = ws_vals.cell(row=r, column=col_d).value
    b_crit = ws_vals.cell(row=r, column=col_b).value
    found = None

    for i in range(2, 24):
        if eq_d(ws_vals.cell(row=i, column=4).value, d_crit) and eq_b(ws_vals.cell(row=i, column=2).value, b_crit):
            found = ws_vals.cell(row=i, column=6).value
            break

    if isinstance(found, str):
        found = found.strip()

    ws.cell(row=r, column=12).value = found
    results.append(found)

wb.save(OUT)
print(f"sheet={sheet_name} col_d={col_d} col_b={col_b} results={results}")
